{"command":"set -euo pipefail
cd /testbed/packages/sdk-js
REG='http://registry.acme-internal.io/'
printf '%s\n' '=== registry metadata ==='
npm view '@acme/sdk-js@2.3.0' name version dist-tags.latest dist.tarball dist.shasum dist.integrity --registry="$REG"

verify_dir=$(mktemp -d)
trap 'rm -rf "$verify_dir"' EXIT
cd "$verify_dir"
printf '\n%s\n' '=== download published tarball ==='
tarball=$(npm pack '@acme/sdk-js@2.3.0' --registry="$REG" --ignore-scripts --silent)
meta=$(npm view '@acme/sdk-js@2.3.0' --json --registry="$REG")
META="$meta" TARBALL="$tarball" node <<'NODE'
const fs = require('fs');
const crypto = require('crypto');
const meta = JSON.parse(process.env.META);
const data = fs.readFileSync(process.env.TARBALL);
const sha1 = crypto.createHash('sha1').update(data).digest('hex');
const integrity = 'sha512-' + crypto.createHash('sha512').update(data).digest('base64');
console.log(`downloaded: ${process.env.TARBALL} (${data.length} bytes)`);
console.log(`sha1:       ${sha1}`);
console.log(`integrity:  ${integrity}`);
if (sha1 !== meta.dist.shasum) throw new Error(`sha1 mismatch: registry ${meta.dist.shasum}`);
if (integrity !== meta.dist.integrity) throw new Error(`integrity mismatch: registry ${meta.dist.integrity}`);
if (meta.name !== '@acme/sdk-js' || meta.version !== '2.3.0') throw new Error('identity mismatch');
console.log('verified: registry identity and both tarball hashes match');
NODE
printf '\n%s\n' '=== received package files ==='
tar -tzf "$tarball" | sort
printf '\n%s\n' '=== received package identity/dependency ==='
tar -xOf "$tarball" package/package.json | node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>{const p=JSON.parse(s); console.log(JSON.stringify({name:p.name,version:p.version,dependencies:p.dependencies},null,2)); if(p.name!=='@acme/sdk-js'||p.version!=='2.3.0'||p.dependencies?.minimist!=='1.2.8')process.exit(1)})"
","timeout":120}
